/// What an anchor does when text is inserted exactly at it.
#[derive(Copy, Clone, PartialEq, Eq, Hash, Debug)]
pub enum Bias { Left, Right }

/// A position remembered at a revision. Plain data; no registration, no Rc, no callbacks.
#[derive(Copy, Clone, PartialEq, Eq, Hash, Debug)]
pub struct Anchor { pub offset: Offset, pub revision: Revision, pub bias: Bias }

#[derive(Debug, PartialEq, Eq)]
pub struct StaleAnchor { pub requested: Revision, pub oldest_available: Revision }

/// Transform rule for one Edit (pre-state offsets):
///   o <  start          -> o
///   o >  old_end        -> o + delta
///   start <= o <= old_end:
///       old empty (pure insert at o): Left -> o, Right -> o + new_len
///       otherwise (inside replaced span): Left -> start, Right -> new_end
pub fn transform_offset(o: Offset, bias: Bias, edit: &Edit) -> Offset;

/// Applied transactions, oldest first. Entry i produced revision `first_revision + i + 1`.
pub struct EditLog { entries: std::collections::VecDeque<Transaction>, first_revision: Revision, locks: std::collections::BTreeMap<Revision, u32> }
impl EditLog {
    pub fn new(at: Revision) -> Self;
    pub fn push(&mut self, tx: Transaction, produced: Revision); // then prunes entries older than the oldest lock
    pub fn lock(&mut self, r: Revision); pub fn unlock(&mut self, r: Revision);
    pub fn oldest_available(&self) -> Revision;
    pub fn entries_since(&self, r: Revision) -> Result<impl Iterator<Item = &Transaction>, StaleAnchor>;
}

impl TextBuffer {
    // field added: log: EditLog
    pub fn anchor(&self, offset: Offset, bias: Bias) -> Anchor; // at current revision
    pub fn resolve(&self, a: Anchor) -> Result<Offset, StaleAnchor>;
    pub fn refresh(&self, a: Anchor) -> Result<Anchor, StaleAnchor>; // resolve and re-stamp at current revision
    pub fn transform(&self, o: Offset, bias: Bias, from: Revision, to: Revision) -> Result<Offset, StaleAnchor>; // from <= to
    pub fn lock_revision(&mut self, r: Revision);
    pub fn unlock_revision(&mut self, r: Revision);
}
